IndiaSignUpUI = IndiaSignUpUI or {}

--开赛时间
BP_INDIA_SIGNUP_TIME = ""
--地图名称
BP_INDIA_SIGNUP_MAP_NAME = ""
--最高获得积分
BP_INDIA_SIGNUP_MAX_CREDIT = 300
--模式名称
BP_INDIA_SIGNUP_MODE_NAME = ""
--uc报名花费
BP_INDIA_SIGNUP_UC_COST = 1
--入场券报名花费
BP_INDIA_SIGNUP_TICKET_COST = 1
--比赛轮次
BP_INDIA_SIGNUP_ROUND = 1
--等级限制
BP_INDIA_SIGNUP_LV_LIMIT = 1
--下段位限制
BP_INDIA_SIGNUP_LV_LIMIT_DOWN = 101;
--上段位限制
BP_INDIA_SIGNUP_LV_LIMIT_UP = -1;
--比赛名称
BP_INDIA_SIGNUP_GAME_NAME = "";

function bp_india_sign_up_RegisterUI()
    LuaClassObj.SubUIWidgetList(bp_india_sign_up,
            {{Path="/Game/UMG/UI_BP/Championship_India/Championship_India_Popup_UIBP.Championship_India_Popup_UIBP_C", Container="Top", ZOrder=BP_ENUM_UI_LEAGUEGAME_LOBBY+3}},
            {"Lobby"},
            false,
            bp_india_sign_up_OnModeSwitched ~= nil,
            true
    );
end

function IndiaSignUpUI.Show(champItemData)
    UIManager.Show(eUIType.eIndiaChampionShipPopUp)
    BP_INDIA_SIGNUP_GAME_NAME = champItemData.title.."：";
    IndiaSignUpUI.itemData = champItemData;
    BP_INDIA_SIGNUP_TIME = TimeUtil.formatUTCToLocal2(champItemData.start_time)
    local modeInfo = Client.GetTableData("ModeTeamTable", champItemData.mode_group);
    if modeInfo and modeInfo.mapName then
        BP_INDIA_SIGNUP_MAP_NAME =  Client.GetTableData("LocalizeRes",modeInfo.mapName).TextValue
        BP_INDIA_SIGNUP_MODE_NAME = DataMgr.GetMsgByID(modeInfo.LabelWords)
    end
    BP_INDIA_SIGNUP_MAX_CREDIT = champItemData.earn_score;
    BP_INDIA_SIGNUP_UC_COST = champItemData.cost;
    BP_INDIA_SIGNUP_TICKET_COST = champItemData.cost_resid;
    if not DataMgr.GetHallDepotItemDataByResID(1702018) or DataMgr.GetHallDepotItemDataByResID(1702018).count < BP_INDIA_SIGNUP_TICKET_COST then
        BP_INDIA_SIGNUP_TICKET_COST = -1;
    end
    for k,v in pairs(IndiaChampionShipLogic.tournaments) do
        if k == champItemData.id then
            --比赛轮次
            BP_INDIA_SIGNUP_ROUND = v.roundlimit
            BP_INDIA_SIGNUP_LV_LIMIT = v.type_data.level_limit
            --[[local modeInfo = Client.GetTableData("ModeTeamTable", v.type_data.mode_group);
            if modeInfo then
                BP_INDIA_SIGNUP_MAP_NAME = DataMgr.GetMsgByID(modeInfo.mapName)
                BP_INDIA_SIGNUP_MODE_NAME = DataMgr.GetMsgByID(modeInfo.LabelWords)
            end--]]

            if v.type_data.min_segment and v.type_data.min_segment>0 then
                BP_INDIA_SIGNUP_LV_LIMIT_DOWN = v.type_data.min_segment;
            else
                BP_INDIA_SIGNUP_LV_LIMIT_DOWN = 101
            end
            if v.type_data.max_segment and v.type_data.max_segment >0 then
                BP_INDIA_SIGNUP_LV_LIMIT_UP = v.type_data.max_segment
            else
                BP_INDIA_SIGNUP_LV_LIMIT_UP = -1;
            end
            BP_INDIA_SIGNUP_GAME_NAME = Client.GetTableData("LocalizeRes",v.type_data.grade+6620).TextValue
            break;
        end
    end

    LuaClassObj.HandleDynamicCreation(bp_india_sign_up);
    LuaClassObj.HandleUIMessage(bp_india_sign_up,"UIShow")
end

function IndiaSignUpUI.Hide()
    UIManager.Hide(eUIType.eIndiaChampionShipPopUp)
    LuaClassObj.HandleUIMessageNoFetch(bp_india_sign_up,"UIHide")
end

